import{_ as o,a0 as s,w as u,s as r,I as n,x as e,a1 as i,A as p,ao as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const P=JSON.parse('{"title":"Dell XPS 13 7390：最好的 Linux 桌面筆記本 | LCTT x X-CMD","titleTemplate":false,"description":"Dell XPS 13 7390：最好的 Linux 桌面筆記本 | LCTT (201912) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Dell XPS 13 7390：最好的 Linux 桌面筆記本 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Dell XPS 13 7390：最好的 Linux 桌面筆記本 | LCTT (201912) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201912/20191204 Dell XPS 13 7390 Review- The Best Laptop For Desktop Linux Users","title":"Dell XPS 13 7390：最好的 Linux 桌面筆記本","tag":"201912","desc":""},"relativePath":"201912/20191204 Dell XPS 13 7390 Review- The Best Laptop For Desktop Linux Users.md","filePath":"[post].md"}'),x={name:"201912/20191204 Dell XPS 13 7390 Review- The Best Laptop For Desktop Linux Users.md"};function d(m,t,L,S,f,T){const l=s("Link");return u(),r("div",null,[t[20]||(t[20]=n("h1",{id:"dell-xps-13-7390-最好的-linux-桌面筆記本",tabindex:"-1"},[e("Dell XPS 13 7390：最好的 Linux 桌面筆記本 "),n("a",{class:"header-anchor",href:"#dell-xps-13-7390-最好的-linux-桌面筆記本","aria-label":"Permalink to “Dell XPS 13 7390：最好的 Linux 桌面筆記本”"},"​")],-1)),t[21]||(t[21]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/201912/11/090509vwdm33q8dwqdgnnx.jpg",alt:""})],-1)),t[22]||(t[22]=n("p",null,"曾經，我們必須進行大量研究、閲讀大量評論，才能找到一種在所選的 Linux 桌面發行版上可以以最少的麻煩工作的機器。而如今，這種日子已經一去不復返了，幾乎每台機器都可以運行 Linux。Linux 內核社區在設備驅動程序支持方面做得非常出色，可以使一切都開箱即用。",-1)),t[23]||(t[23]=n("p",null,[e("不過，有的是"),n("strong",null,"可以"),e("運行 Linux d 機器，有的是運行 Linux 的機器。戴爾計算機屬於後一類。五年前，Barton George 在戴爾內部啓動了一項計劃，將桌面版 Linux 引入到消費級的高端戴爾系統。從一台機器開始，到現在整套從產品線的高端筆記本電腦和台式機都可以運行 Linux。")],-1)),t[24]||(t[24]=n("p",null,"在這些機器中，XPS 13 是我的最愛。儘管我需要一個功能強大的台式機來處理 4K UHD、多機位視頻製作，但我還需要一台超便攜的筆記本電腦，可以隨身攜帶，而不必擔心笨重的背包和充電器。XPS 13 也是我的第一台筆記本電腦，陪了我 7 年多。因此，是的，這還有一個懷舊因素。",-1)),n("p",null,[t[2]||(t[2]=e("戴爾幾乎每年都會更新其 XPS 產品線，並且最新的",-1)),i(l,{href:"https://bartongeorge.io/2019/08/21/please-welcome-the-9th-generation-of-the-xps-13-developer-edition/"},{default:p(()=>[...t[0]||(t[0]=[e("產品展示宣佈於 10 月",-1)])]),_:1}),t[3]||(t[3]=e("。[XPS 13（7390）] ",-1)),i(l,{href:"https://blog.dell.com/en-us/dells-new-consumer-pc-portfolio-unveiled-ifa-2019/"},{default:p(()=>[...t[1]||(t[1]=[e("4",-1)])]),_:1}),t[4]||(t[4]=e(" 是該系列的增量更新，而且戴爾非常樂意向我寄來一台測評設備。",-1))]),t[25]||(t[25]=a('<p><img src="https://img.linux.net.cn/data/attachment/album/201912/11/090524z2xk670shp0080mx.jpg" alt=""></p><p>它由 6 核 Core i7-10710U CPU 所支持。它配備 16GB 內存和 1TB SSD。在 1.10 GHz 的基本頻率（可以超頻到 4.1 GHz）的情況下，這是一台用於常規工作負載的出色機器。它沒有使用任何專用的 GPU，因此它並不適合進行遊戲或從源代碼進行編譯的 Gentoo Linux 或 Arch Linux。但是，我確實設法在上面運行了一些 Steam 遊戲。</p><p>如果你想運行 Kubernetes 集羣、AI 框架或虛擬現實，那麼 Precision 系列中還有更強大的機器，這些機器可以運行 Red Hat Enterprise Linux 和 Ubuntu。</p><p>該機器的底盤與上一代相同。邊框保持與上一代一樣的薄，依舊比 MacBook 和微軟的 Surface Pro 薄。</p><p>它具有三個端口，其中兩個是 USB-C Thunderbolt 3，可用於連接 4K 顯示器、USB 附件以及用於對等網絡的計算機之間的高速數據傳輸。</p><p>它還具有一個 microSD 插槽。作為視頻記者，SD 卡插槽會更有用。大量使用樹莓派的用户也會喜歡這種卡。</p><p>它具有 4 個麥克風和一個改進的攝像頭，該攝像頭現在位於頂部（再見，鼻孔攝像頭！）。</p><p>XPS 13（7390）光滑纖薄。它的重量僅為 2.7 磅（1.2kg），可以與蘋果的 MacBook Air 相提並論。 這台機器可以成為你的旅行伴侶，並且可以執行日常任務，例如檢查電子郵件、瀏覽網絡和寫作。</p><p>其 4K UHD 屏幕支持 HDR，這意味着你將可以盡享《The Mandalorian》的全部美妙之處。另外，車載揚聲器並沒有那麼好，聽起來有些沉悶。它們適合進行視頻聊天或休閒的 YouTube 觀看，但是如果你想在今年晚些時候觀看《The Witcher》劇集，或者想欣賞 Amazon、Apple Music 或 YouTube Music 的音樂，則需要耳機或外接揚聲器。</p><p><img src="https://img.linux.net.cn/data/attachment/album/201912/11/091107p8de88jk5pwffd4a.jpg" alt=""></p><p>但是，在插入充電線之前，你可以能使用這台機器多少時間？在正常工作量的情況下，它為我提供了大約 7-8 個小時的電池續航時間：我打開了幾個選項卡瀏覽網絡，只是看看電影或聽音樂。多任務處理，尤其是各種 Web 活動，都會加速消耗電池電量。在 Linux 上進行一些微調可能會給你帶來更多的續航時間，而在 Windows 10 上，我可以使用 10 多個小時呢！</p><p>作為仍在從事大量寫作工作的視頻記者，我非常喜歡鍵盤。但是，我們這麼多年來在 Linux 台式機上聽到的觸控板故事一直沒變：它與 MacBook 或 Windows 上的品質相差甚遠。這或許有一天能改變。值得稱道的是，他們確實發佈了可增強體驗的觸控板驅動程序，但我沒有運行此係統隨附的提供的 Ubuntu 18.04 LTS。我全新安裝了 Ubuntu 19.10，因為 Gnome 在 18.04 中的運行速度非常慢。我嘗試過 openSUSE Tumbleweed、Zorin OS、elementary OS、Fedora、KDE neon 和 Arch Linux。一切正常，儘管有些需要額外的努力才能運行。</p><p>那麼，該系統適用於誰？顯然，這是給那些想要設計精良的、他們信賴的品牌的高端機器的專業人士打造的。適用於喜歡 MacBook Air，但更喜歡 Linux 台式機生態系統的用户。適用於那些希望使用 Linux 來工作，而不是使 Linux 可以工作的人。</p><p>我使用這台機器一週的時間，進一步説明了為什麼我如此喜歡戴爾的 XPS 系列。它們是目前最好的 Linux 筆記本電腦。這款 XPS 13（7390），你值得擁有！</p><hr>',15)),n("p",null,[t[6]||(t[6]=e("via: ",-1)),i(l,{href:"https://www.linux.com/articles/dell-xps-13-7390-review-the-best-laptop-for-desktop-linux-user/"},{default:p(()=>[...t[5]||(t[5]=[e("https://www.linux.com/articles/dell-xps-13-7390-review-the-best-laptop-for-desktop-linux-user/",-1)])]),_:1})]),n("p",null,[t[11]||(t[11]=e("作者：",-1)),i(l,{href:"https://www.linux.com/author/swapnil/"},{default:p(()=>[...t[7]||(t[7]=[e("Swapnil Bhartiya",-1)])]),_:1}),t[12]||(t[12]=e(" 選題：",-1)),i(l,{href:"https://github.com/lujun9972"},{default:p(()=>[...t[8]||(t[8]=[e("lujun9972",-1)])]),_:1}),t[13]||(t[13]=e(" 譯者：",-1)),i(l,{href:"https://github.com/wxy"},{default:p(()=>[...t[9]||(t[9]=[e("wxy",-1)])]),_:1}),t[14]||(t[14]=e(" 校對：",-1)),i(l,{href:"https://github.com/wxy"},{default:p(()=>[...t[10]||(t[10]=[e("wxy",-1)])]),_:1})]),n("p",null,[t[17]||(t[17]=e("本文由 ",-1)),i(l,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[15]||(t[15]=[e("LCTT",-1)])]),_:1}),t[18]||(t[18]=e(" 原創編譯，",-1)),i(l,{href:"https://linux.cn/"},{default:p(()=>[...t[16]||(t[16]=[e("Linux中國",-1)])]),_:1}),t[19]||(t[19]=e(" 榮譽推出",-1))])])}const g=o(x,[["render",d]]);export{P as __pageData,g as default};
